def main():
    source=json.loads(SOURCE.read_text())['lessons'];out=[]
    for s,t in zip(source,PAYLOAD):
        assert len(t['titles'])==len(t['bodies'])==len(s['sections'])
        assert len(t['meanings'])==len(s['terms']);assert len(t['questions'])==len(s['questions'])
        l={'id':s['id'],'title':t['title'],'reading':s['reading'],'sourceRevision':s['revision'],'status':'translated_ai_unreviewed',
           'objectives':[{**o,'text':t['objective']} for o in s['objectives']],
           'sections':[{**sec,'title':title,'body':body} for sec,title,body in zip(s['sections'],t['titles'],t['bodies'])],
           'terms':[{**term,'meaning':meaning} for term,meaning in zip(s['terms'],t['meanings'])],
           'example':{'situation':t['situation'],'steps':t['steps']},
           'practice':{'prompt':t['practice'],'expectedPoints':t['points']},
           'questions':[{**q,'prompt':a[0],'choices':a[1],'explanation':a[2]} for q,a in zip(s['questions'],t['questions'])],
           'illustration':{**s['illustration'],'caption':t['caption'],'alt':t['alt']}}
        out.append(l)
    path=ROOT.parent/'hotel-v2-translations/tl.json';path.parent.mkdir(exist_ok=True)
    path.write_text(json.dumps({'lessons':out},ensure_ascii=False,indent=2)+'\n');print(path)

if __name__=='__main__':main()
